    one('SEMIO_G1_WORKSPACE:repositoryRootV1,','SEMIO_G1_WORKSPACE:repository.root,')
    one('pathToFileURL(resolve("🧰️framework/🔨️modules/🏃️process/📦️packages/🟦️typescript/🧭️routing/🟦️.ts")).href','pathToFileURL(join(testCheckoutRootV1(),"🧰️framework/🔨️modules/🏃️process/📦️packages/🟦️typescript/🧭️routing/🟦️.ts")).href')
    one('\n  })));\n  const result=Object.fromEntries(outputs)','\n  })),{maximumElapsedMilliseconds:280000});\n  const result=Object.fromEntries(outputs)')
    one('try{await withBuildTestInvocationV1(original=>Promise.all(runs.map(run=>withRepositoryBuildInferenceDatasetV1(repository.root,original,scriptCompilerAdmissionControlV1(original,"graph:dataset-retirement",0),run.dataset,async scope=>{await scope.retire();expect(existsSync(scope.root)).toBe(false);}))));}',
        'try{await repository.invoke(original=>Promise.all(runs.map(run=>withRepositoryBuildInferenceDatasetV1(repository.root,original,scriptCompilerAdmissionControlV1(original,"graph:dataset-retirement",0),run.dataset,async scope=>{await scope.retire();expect(existsSync(scope.root)).toBe(false);}))),{maximumElapsedMilliseconds:120000});}')
    one("const out={};write(fixture.race.extra.path","const out={},racy=observation.OBSERVATION_LIMITS_V1.racyMilliseconds+500,wait=()=>new Promise(resolve=>setTimeout(resolve,racy)),pass=async()=>({result:await run(fixture.concurrency.parallel),counts:counts()});write(fixture.race.extra.path")
    one("out.warm={result:await run(fixture.concurrency.parallel),counts:counts()};","await wait();out.settle=await pass();out.warm=await pass();")
    one("write(fixture.stale.extra.path,fixture.stale.extra.content);write(fixture.stale.path,fixture.stale.content);out.stale={result:await run(fixture.concurrency.parallel),counts:counts()};","write(fixture.stale.extra.path,fixture.stale.extra.content);write(fixture.stale.path,fixture.stale.content);await pass();await wait();out.stale=await pass();")
    one("let foreignLibraryFacts=0,authorityRows=0;","let foreignLibraryFacts=0,authorityRows=0;const foreignPaths=new Set();")
    one("foreignLibraryFacts+=header.observations.filter(row=>row.kind==='file'&&row.path.startsWith(library)).length;}","const foreign=header.observations.filter(row=>row.kind==='file'&&row.path.startsWith(library));foreignLibraryFacts+=foreign.length;for(const row of foreign)foreignPaths.add(row.path);}")
